/* =====================================================================================
   GODR RISQUES RADIOLOGIQUES
   ===================================================================================== */

var GODRRAD = 'GODR Interventions relatives aux risques radiologiques, version du 01/01/2017 (SDIS 86)';

VSAV.chap({
  id: 'gn-godr-rad', part: 'gn', seq: GN4,
  title: 'GODR Risques radiologiques : se protéger et prendre en charge une victime contaminée', short: 'GODR radiologique', motif: 'molecule',
  sources: [GODRRAD],
  summary: 'Rayonnements alpha, bêta, gamma ; irradiation et contamination ; unités (Bq, Gy, Sv, débit de dose) ; protection par le temps, la distance et l’écran ; colis et étiquettes de transport ; zonage, périmètres et marche des opérations RAD ; prise en charge d’une victime contaminée avec l’équipe VSAV.',
  why: '<b>Pourquoi le VSAV est-il concerné ?</b> Dans une intervention radiologique, l’<b>équipe VSAV reçoit la victime à la sortie de la zone</b> sans y entrer. Et la règle d’or est simple : <b>l’urgence médicale prime sur le risque radiologique</b>. Une victime irradiée n’est pas dangereuse ; une victime contaminée l’est par les poussières qu’elle porte, ce qui se maîtrise avec un masque FFP2, des gants et une enveloppe.',
  sections: [
    { id: 'rayonnements', t: 'Rayonnements, irradiation et contamination', ic: 'molecule', src: GODRRAD + ', 1re et 2e parties',
      html: '<div class="tw"><table><thead><tr><th>Rayonnement</th><th>Pénétration</th><th>Arrêté par</th></tr></thead><tbody><tr><td><b>Alpha</b></td><td>Quelques cm d’air ; très ionisant</td><td>Une feuille de papier</td></tr><tr><td><b>Bêta</b></td><td>Plus pénétrant</td><td>Plexiglas, aluminium</td></tr><tr><td><b>Gamma, X</b></td><td>Très pénétrant, peu ionisant</td><td>Seulement <b>atténué</b> (plomb, béton)</td></tr></tbody></table></div>' +
        '<ul class="check"><li><b>Irradiation</b> : exposition à distance à une source (comme au soleil) ; elle cesse quand on s’éloigne ou qu’on interpose un écran ; une personne irradiée <b>n’est pas radioactive</b> et ne présente aucun danger pour les autres.</li><li><b>Contamination</b> : dépôt de substances radioactives (poussières, liquides, gaz) sur la peau (externe) ou dans l’organisme (interne) par voie <b>respiratoire</b>, <b>digestive</b> ou <b>cutanée</b> (surtout par une plaie). Les émetteurs alpha et bêta sont les plus dangereux à l’intérieur du corps.</li><li><b>Effets</b> : déterministes au-delà d’un seuil (DL 50 ≈ 4 Sv) ; aléatoires (cancers) des années plus tard.</li></ul>' },
    { id: 'unites', t: 'Unités et étiquettes', ic: 'list', src: GODRRAD + ', 3e et 5e parties',
      html: '<div class="tw"><table><thead><tr><th>Grandeur</th><th>Unité</th></tr></thead><tbody><tr><td>Activité (désintégrations par seconde)</td><td>Becquerel (Bq) ; 1 Ci = 37 GBq</td></tr><tr><td>Dose absorbée</td><td>Gray (Gy)</td></tr><tr><td>Équivalent de dose (effet biologique)</td><td>Sievert (Sv)</td></tr><tr><td><b>Débit de dose</b> (évaluation instantanée du risque)</td><td>Gy/h ou <b>Sv/h</b> (souvent µSv/h)</td></tr></tbody></table></div>' +
        '<ul class="check"><li>Sources <b>scellées</b> (enveloppe étanche : irradiation) ou <b>non scellées</b> (poudre, liquide, gaz : contamination possible).</li><li>Transport : classe 7 ; panneau orange à l’avant du véhicule, plaque « 7D » à l’arrière, étiquettes sur les colis ; plus la catégorie est élevée, plus le débit de dose au contact est fort ; l’indice de transport reflète le débit de dose à 1 m.</li></ul>' },
    { id: 'protection', t: 'Se protéger : temps, distance, écran', ic: 'shield', src: GODRRAD + ', 4e partie',
      html: '<ul class="check"><li><b>Temps</b> : la dose reçue est proportionnelle au temps passé ; rester le moins longtemps possible.</li><li><b>Distance</b> : pour un rayonnement gamma, le débit de dose diminue avec le <b>carré de la distance</b> : <b>doubler la distance divise la dose par 4</b>.</li><li><b>Écran</b> : adapté au rayonnement (papier, plexiglas, plomb, béton).</li><li><b>Contamination</b> : s’isoler du milieu : combinaison étanche, gants, surbottes, appareil respiratoire filtrant (cartouche P3) ou <b>ARI si O₂ &lt; 17 % ou présence de CO</b> (incendie). Ces tenues protègent de la contamination, <b>pas de l’irradiation</b>.</li><li>Dosimétrie active et passive pour les intervenants spécialisés.</li></ul>' +
        '<p>Zonage : zone d’exclusion, <b>SAS</b> de contrôle et de déshabillage, zones de soutien spécialisé et général, zone public. Périmètre affiné par les mesures (par exemple 2,5 µSv/h pour l’irradiation, deux fois le bruit de fond pour la contamination). Accident de transport de matières radioactives : exclusion de <b>100 m</b> a priori avant les mesures.</p>' },
    { id: 'victime', t: 'Prise en charge d’une victime contaminée', ic: 'stretcher', src: GODRRAD + ', fiche opérationnelle « victime contaminée »',
      steps: [
        'Rappel : l’urgence médicale prime sur le risque radiologique. Dégagement d’urgence seulement si la victime est exposée à une source importante.',
        'Engagement minimum : une équipe de sauvetage RAD (4 équipiers) en zone, et une équipe d’évacuation VSAV (2 équipiers) qui n’entre pas en zone contaminée.',
        'Protéger la victime : masque FFP2, charlotte sur les cheveux ; limiter le contact avec les surfaces contaminées.',
        'Matelas immobilisateur ou plan dur protégé par une bâche ; transfert de la victime (pont néerlandais) ; 1er contrôle de contamination.',
        'Si la victime est contaminée : déshabillage par découpe des vêtements ; l’envelopper (housse, bâche double, couverture de survie) le plus hermétiquement possible.',
        'Sortie de zone : 2e contrôle, puis remise à l’équipe VSAV pour un transport direct vers l’hôpital ; victime en urgence absolue ou contaminée interne = évacuation.',
        'Déchets (gants, surbottes, ciseaux) dans un sac DASRI dédié ; contrôle a posteriori du personnel, du matériel et du site.'
      ], stepsTitle: 'Conduite à tenir',
      after: '<div class="callout warn"><b>Consignes aux impliqués et aux premiers intervenants</b>Minimum de mouvements, ne pas porter les mains au visage, ne pas manger, boire ni fumer, masque FFP2 ; pour l’équipage VSAV : kit de protection avec masque FFP2. Attention à l’<b>hyperthermie</b> et à la déshydratation de la victime enveloppée.</div>' }
  ],
  key: ['Alpha : papier ; bêta : plexiglas ; gamma : seulement atténué par le plomb ou le béton.', 'Irradié = non dangereux pour les autres ; contaminé = poussières à maîtriser.', 'Temps, distance, écran ; doubler la distance divise la dose par 4.', 'Tenue de protection = contre la contamination, pas contre l’irradiation.', 'Urgence médicale > risque radiologique.', 'VSAV hors zone contaminée, reçoit la victime enveloppée après contrôle.', 'Victime : FFP2, charlotte, déshabillage par découpe, enveloppe.', 'Accident de transport radioactif : 100 m a priori.'],
  traps: ['Refuser de soigner une victime irradiée par peur d’être contaminé.', 'Retarder un geste d’urgence vitale pour le risque radiologique.', 'Croire qu’une combinaison protège des rayonnements gamma.', 'Entrer en zone contaminée avec l’équipe VSAV.', 'Oublier le risque d’hyperthermie d’une victime emballée.'],
  quiz: [
    { q: 'Une victime seulement irradiée (sans contamination) :', c: ['Ne présente aucun danger radioactif pour les secouristes', 'Est radioactive et doit être isolée', 'Contamine le VSAV', 'Doit être décontaminée à l’eau'], e: 'GODR RAD, 2e partie A.', s: 'rayonnements' },
    { q: 'Quel rayonnement est arrêté par une simple feuille de papier ?', c: ['Alpha', 'Gamma', 'X', 'Neutrons'], e: 'GODR RAD, 1re partie.', s: 'rayonnements' },
    { q: 'En doublant la distance à une source gamma, le débit de dose est :', c: ['Divisé par 4', 'Divisé par 2', 'Inchangé', 'Multiplié par 2'], e: 'GODR RAD, 4e partie A.', s: 'protection' },
    { q: 'Une tenue de protection type combinaison étanche protège :', c: ['De la contamination, pas de l’irradiation', 'De l’irradiation gamma', 'De tout', 'De rien'], e: 'GODR RAD, 4e partie B.', s: 'protection' },
    { q: 'Qu’est-ce qui prime lors d’une intervention radiologique avec une victime grave ?', c: ['L’urgence médicale', 'La mesure de la contamination', 'L’attente des spécialistes IRSN', 'La décontamination complète'], e: 'GODR RAD, fiche victime contaminée.', s: 'victime' },
    { q: 'Dans quelle unité s’exprime le débit d’équivalent de dose ?', c: ['Sievert par heure (Sv/h)', 'Becquerel', 'Gray', 'Curie'], e: 'GODR RAD, 3e partie D.', s: 'unites' },
    { q: 'L’équipe VSAV, lors de la prise en charge d’une victime contaminée :', c: ['Reste hors zone contaminée et reçoit la victime enveloppée après contrôle', 'Entre en zone d’exclusion pour la chercher', 'Décontamine elle-même la victime', 'Attend la fin de l’intervention'], e: 'GODR RAD, fiche victime contaminée.', s: 'victime' }
  ]
});
